-- V1__init_schema.sql — Source of truth for Visit Polzela database
-- Creates schema and seeds all POI data from the original flat files.

-- =============================================================================
-- DDL
-- =============================================================================

CREATE TABLE point_of_interest (
    poi_key           VARCHAR(64)  PRIMARY KEY,
    short_description VARCHAR(512),
    display_order     INT          NOT NULL DEFAULT 0,
    osm_url           VARCHAR(512),
    google_maps_url   VARCHAR(512),
    apple_maps_url    VARCHAR(512)
);

CREATE TABLE poi_translation (
    poi_key      VARCHAR(64) NOT NULL REFERENCES point_of_interest(poi_key) ON DELETE CASCADE,
    lang         VARCHAR(2)  NOT NULL,
    display_name VARCHAR(512),
    description  TEXT,
    PRIMARY KEY (poi_key, lang)
);

CREATE TABLE poi_image (
    id         BIGSERIAL   PRIMARY KEY,
    poi_key    VARCHAR(64) NOT NULL REFERENCES point_of_interest(poi_key) ON DELETE CASCADE,
    image_path VARCHAR(256) NOT NULL,
    sort_order INT          NOT NULL DEFAULT 0
);

CREATE TABLE ui_text (
    text_key VARCHAR(64) NOT NULL,
    lang     VARCHAR(2)  NOT NULL,
    value    VARCHAR(512),
    PRIMARY KEY (text_key, lang)
);

